package dev.navifold.player;
import android.content.*;import android.net.*;import android.os.*;import android.app.*;import java.util.*;
/** Own UID counters only. Transport attribution is sampled and deliberately labeled approximate. */
final class NetworkUsage {
 private static NetworkUsage instance;
 static synchronized NetworkUsage get(Context c){if(instance==null)instance=new NetworkUsage(c.getApplicationContext());return instance;}
 final Context context;final SharedPreferences prefs;final ConnectivityManager connectivity;private long savedAt,sampledAt,lastRx=-1,lastTx=-1,rx,tx,meteredBytes,cellularBytes;private String day="";private boolean measured;
 volatile boolean metered,cellular,connected;volatile String network="오프라인";
 private NetworkUsage(Context c){context=c;prefs=c.getSharedPreferences("network-usage",0);connectivity=c.getSystemService(ConnectivityManager.class);day=prefs.getString("day","");rx=prefs.getLong("rx",0);tx=prefs.getLong("tx",0);meteredBytes=prefs.getLong("meteredBytes",0);cellularBytes=prefs.getLong("cellularBytes",0);long boot=System.currentTimeMillis()-SystemClock.elapsedRealtime();if(Math.abs(boot-prefs.getLong("boot",0))<120000){lastRx=prefs.getLong("lastRx",-1);lastTx=prefs.getLong("lastTx",-1);}metered=prefs.getBoolean("lastMetered",false);cellular=prefs.getBoolean("lastCellular",false);sample(true);refresh();try{connectivity.registerDefaultNetworkCallback(new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){changed();}public void onLost(Network n){changed();}public void onCapabilitiesChanged(Network n,NetworkCapabilities caps){changed();}});}catch(RuntimeException ignored){}}
 private synchronized void changed(){sample(true);refresh();}
 private synchronized void refresh(){try{NetworkCapabilities c=connectivity.getNetworkCapabilities(connectivity.getActiveNetwork());connected=c!=null;metered=c!=null&&connectivity.isActiveNetworkMetered();cellular=c!=null&&c.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR);network=c==null?"오프라인":cellular?"모바일":c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?"유선":c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)?"VPN":"네트워크";}catch(RuntimeException e){connected=false;metered=false;cellular=false;network="확인 불가";}}
 synchronized void sample(boolean force){long elapsed=SystemClock.elapsedRealtime();if(!force&&elapsed-sampledAt<5000)return;sampledAt=elapsed;String today=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date());long currentRx=TrafficStats.getUidRxBytes(android.os.Process.myUid()),currentTx=TrafficStats.getUidTxBytes(android.os.Process.myUid());measured=currentRx>=0&&currentTx>=0;if(!today.equals(day)){day=today;rx=tx=meteredBytes=cellularBytes=0;lastRx=currentRx;lastTx=currentTx;}long dr=DataPolicy.delta(lastRx,currentRx),dt=DataPolicy.delta(lastTx,currentTx);rx+=dr;tx+=dt;if(metered)meteredBytes+=dr+dt;if(cellular)cellularBytes+=dr+dt;lastRx=currentRx;lastTx=currentTx;if(force||elapsed-savedAt>=30000){savedAt=elapsed;prefs.edit().putString("day",day).putLong("rx",rx).putLong("tx",tx).putLong("meteredBytes",meteredBytes).putLong("cellularBytes",cellularBytes).putLong("lastRx",lastRx).putLong("lastTx",lastTx).putLong("boot",System.currentTimeMillis()-elapsed).putBoolean("lastMetered",metered).putBoolean("lastCellular",cellular).apply();}notifyLimit();}
 synchronized String summary(){sample(false);return network+(metered?" · 요금제 연결":"")+"\n\n오늘 NaviFold 전체 · "+bytes(rx+tx)+"\n수신 "+bytes(rx)+" · 송신 "+bytes(tx)+"\n요금제 연결 추정 · "+bytes(meteredBytes)+"\n모바일 추정 · "+bytes(cellularBytes)+(measured?"":"\n이 기기는 앱 전송량 조회를 지원하지 않습니다.");}
 String bytes(long b){return android.text.format.Formatter.formatFileSize(context,Math.max(0,b));}
 synchronized boolean overLimit(){return DataPolicy.threshold(meteredBytes,prefs.getInt("limitMb",500));}
 boolean economy(){return DataPolicy.economy(prefs.getBoolean("economy",false),metered);}
 static boolean original(boolean requested){NetworkUsage n=instance;return requested&&(n==null||!n.economy());}
 static int bitrate(int requested){NetworkUsage n=instance;return n!=null&&n.economy()?Math.min(192,requested):requested;}
 private void notifyLimit(){int limit=prefs.getInt("limitMb",500);if(!prefs.getBoolean("warnings",true)||!DataPolicy.threshold(meteredBytes,limit)||day.equals(prefs.getString("notifiedDay",""))&&limit==prefs.getInt("notifiedLimit",0))return;NotificationManager nm=context.getSystemService(NotificationManager.class);if(nm==null||!nm.areNotificationsEnabled()||Build.VERSION.SDK_INT>=33&&context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;nm.createNotificationChannel(new NotificationChannel("navifold_data","NaviFold 데이터 사용량",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(context,904,new Intent(context,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{nm.notify(904,new Notification.Builder(context,"navifold_data").setSmallIcon(R.drawable.ic_stat_music).setContentTitle("NaviFold 데이터 사용량 알림").setContentText("오늘 요금제 연결 추정 "+bytes(meteredBytes)+" · "+limit+" MB 기준 도달").setContentIntent(open).setAutoCancel(true).build());prefs.edit().putString("notifiedDay",day).putInt("notifiedLimit",limit).apply();}catch(SecurityException ignored){}}
 synchronized void reset(){rx=tx=meteredBytes=cellularBytes=0;lastRx=TrafficStats.getUidRxBytes(android.os.Process.myUid());lastTx=TrafficStats.getUidTxBytes(android.os.Process.myUid());prefs.edit().remove("notifiedDay").apply();sample(true);}
}
